/**
 * Eval/test mode (T13, AGENTS.md §6): external pre/post questions,
 * per-participant records, CSV export. Eval questions come from
 * data/eval/questions.json — supplied by the OWNER from real external
 * sources, NEVER generated by the app's pipeline — and stay separate from
 * generated in-app quizzes (different IDs, different storage keys, no
 * pipeline code touches them). This module holds schema + CSV; records
 * live in lib/eval-store.ts, UI in components/test-mode.tsx.
 */
import { z } from "zod";
import sampleQuestions from "../data/eval/questions.json";
import type { EvalRecord } from "./eval-store";

/** One external question (owner file shape; UI-only, pipeline-external). */
export const evalQuestionSchema = z.object({
  id: z.string().min(1),
  kind: z.literal("mcq"),
  prompt: z.string().min(1),
  options: z.array(z.string().min(1)).min(2),
  answer: z.number().int().nonnegative(),
  explanation: z.string().min(1),
});

export const evalQuestionsSchema = z.object({
  title: z.string().min(1),
  /** Present exactly when the file is the built-in SAMPLE, not owner-supplied. */
  notice: z.string().min(1).optional(),
  pre: z.array(evalQuestionSchema).min(1),
  post: z.array(evalQuestionSchema).min(1),
});

export type EvalQuestion = z.infer<typeof evalQuestionSchema>;
export type EvalQuestions = z.infer<typeof evalQuestionsSchema>;

/** Returns null when the owner file is missing or does not validate. */
export function parseEvalQuestions(raw: unknown): EvalQuestions | null {
  try {
    const parsed = evalQuestionsSchema.parse(raw);
    for (const q of [...parsed.pre, ...parsed.post]) {
      if (q.answer >= q.options.length) return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

/** Bundled SAMPLE (imported, not fetched), labeled as a placeholder. */
export function loadSampleEvalQuestions(): EvalQuestions {
  const parsed = parseEvalQuestions(sampleQuestions);
  if (!parsed) throw new Error("broken sample eval questions");
  return parsed;
}

/** True exactly when the questions in play are the sample placeholder. */
export function isSampleQuestions(qs: EvalQuestions): boolean {
  return qs.notice !== undefined;
}

/// ---- CSV export -----------------------------------------------------------

function iso(now: number): string {
  return new Date(now).toISOString();
}

function csvCell(v: string | number | null): string {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

/** One row per participant per part (pre/post), §6: scores + timestamps. */
export function buildEvalCsv(records: EvalRecord[], now: number): string {
  const header = [
    "participant",
    "part",
    "started_at",
    "finished_at",
    "n_questions",
    "n_correct",
    "fraction_correct",
    "exported_at",
  ];
  const lines = [header.map(csvCell).join(",")];
  for (const r of records) {
    for (const part of ["pre", "post"] as const) {
      const p = r[part];
      const n = p.answers.length;
      const c = p.answers.filter((a) => a.correct).length;
      lines.push(
        [
          r.name,
          part,
          iso(p.startedAt),
          p.finishedAt === null ? "" : iso(p.finishedAt),
          n,
          c,
          n > 0 ? (c / n).toFixed(3) : "",
          iso(now),
        ]
          .map(csvCell)
          .join(","),
      );
    }
  }
  return `${lines.join("\n")}\n`;
}

/** Timestamped download of the CSV (§6: log scores with timestamps). */
export function exportEvalCsv(csv: string, name = "eduvoid-eval-sessions.csv"): void {
  if (typeof document === "undefined") return;
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}
